<?php
namespace App\Console\Commands;
use App\Services\YouTubeSyncService; use Illuminate\Console\Command;
class SyncYouTube extends Command { protected $signature='youtube:sync {--feed-file= : Import a previously downloaded official YouTube RSS feed} {--flat-file= : Import tab-separated channel metadata (id, title, thumbnail, duration, views)}'; protected $description='Synchronize videos from the configured YouTube channel'; public function handle(YouTubeSyncService $sync){try{$feed=$this->option('feed-file');$flat=$this->option('flat-file');$file=$feed?:$flat;if($file&&!is_file($file))throw new \RuntimeException('The supplied import file does not exist.');$count=$feed?$sync->syncFeedXml(file_get_contents($feed)):($flat?$sync->syncFlatFile($flat):$sync->sync());$this->info("Synchronized {$count} videos.");return self::SUCCESS;}catch(\Throwable $e){$this->error($e->getMessage());return self::FAILURE;}} }
